/* Operational queues share the staff API's authorization and server persistence. */
let workTasks=[],queueEntries=[],taskOffset=0,queueOffset=0,taskGeneration=0,queueGeneration=0,taskEditing=null,offerEditing=null,bookingEntry=null;
const manageQueue=()=>workspace&&['administrator','supervisor','intake'].includes(workspace.role);
const taskStaffName=id=>workspace?.task_staff.find(s=>s.id===id)?.name||(id?id+' (unavailable)':'Unassigned');
const caseSelectHTML=()=>workspace.cases.map(c=>`<option value="${escapeHTML(c.id)}">${escapeHTML(c.label)}</option>`).join('');
const prioritiesHTML='<option>Normal</option><option>High</option><option>Low</option>';
byId('staff-app').insertAdjacentHTML('beforeend',`<section id="tasks-panel" class="panel" hidden><div class="panel-title"><div><h2>Staff follow-up board</h2><p>Assign the next step, keep due dates clear, and close the loop.</p></div><button id="new-work-task" class="primary">＋ Task</button></div><div class="filters"><label>Show<select id="task-state-filter"><option value="Open">Open tasks</option><option value="Overdue">Overdue</option><option value="Done">Completed</option><option value="All">All tasks</option></select></label><label>Assigned to<select id="task-assignee-filter"></select></label><label>Priority<select id="task-priority-filter"><option value="">All priorities</option>${prioritiesHTML}</select></label><label>Search loaded tasks<input id="task-search" type="search" placeholder="Task or case"></label></div><div class="queue-toolbar"><p id="task-count" class="muted" role="status"></p><button id="refresh-tasks">Refresh tasks</button></div><div id="task-board"></div><button id="more-tasks" hidden>Load more tasks</button></section><section id="waitlist-panel" class="panel" hidden><div class="panel-title"><div><h2>Make an opening count.</h2><p>A staff-managed waitlist for available session slots.</p></div><button id="new-waitlist" class="primary">＋ Add to waitlist</button></div><p class="queue-note">Offers recorded here do not reserve a slot or send a message. Staff confirms acceptance before booking; the slot is checked again at booking.</p><div class="queue-toolbar"><label>Show<select id="waitlist-state-filter"><option value="Active">Active entries</option><option>Waiting</option><option>Offered</option><option>Booked</option><option>Withdrawn</option><option value="All">All entries</option></select></label><button id="refresh-waitlist">Refresh waitlist</button></div><p id="waitlist-count" class="muted" role="status"></p><div id="waitlist-board"></div><button id="more-waitlist" hidden>Load more entries</button></section>`);
function opsDialog(id,html){const d=document.createElement('dialog');d.id=id;d.innerHTML=html;document.body.append(d);d.querySelectorAll('[data-ops-close]').forEach(b=>b.onclick=()=>d.close());return d}
const taskDialog=opsDialog('work-task-dialog',`<form id="work-task-form"><div class="dialog-heading"><h2 id="work-task-heading">Create follow-up task</h2><button type="button" data-ops-close aria-label="Close task">×</button></div><label>Case<select id="work-task-case" required></select></label><label>Task<input id="work-task-title" maxlength="150" required></label><label>Assigned staff<select id="work-task-assignee" required></select></label><div class="form-grid"><label>Due date<input id="work-task-due" type="date" required></label><label>Priority<select id="work-task-priority">${prioritiesHTML}</select></label></div><p id="work-task-error" class="error" role="alert" hidden></p><div class="dialog-actions"><button type="button" data-ops-close>Cancel</button><button class="primary">Save task</button></div></form>`);
const queueDialog=opsDialog('waitlist-dialog',`<form id="waitlist-form"><div class="dialog-heading"><h2>Add a waitlist request</h2><button type="button" data-ops-close aria-label="Close waitlist request">×</button></div><label>Case<select id="waitlist-case" required></select></label><label>Service preference<input id="waitlist-service" required maxlength="80" placeholder="e.g. Parent coaching"></label><div class="form-grid"><label>Earliest session date<input id="waitlist-earliest" type="date" required></label><label>Queue priority<select id="waitlist-priority">${prioritiesHTML}</select></label></div><p class="muted">Queue priority is an administrative setting. It does not establish clinical urgency.</p><p id="waitlist-error" class="error" role="alert" hidden></p><div class="dialog-actions"><button type="button" data-ops-close>Cancel</button><button class="primary">Add request</button></div></form>`);
const offerDialog=opsDialog('offer-dialog',`<form id="offer-form"><div class="dialog-heading"><h2>Record a slot offer</h2><button type="button" data-ops-close aria-label="Close slot offer">×</button></div><p id="offer-case" class="muted"></p><label>Assigned therapist<select id="offer-clinician" required></select></label><label>Session title<input id="offer-title" required maxlength="120"></label><div class="form-grid"><label>Date<input id="offer-date" type="date" required></label><label>Time<input id="offer-time" type="time" required value="09:00"></label><label>Duration (minutes)<input id="offer-duration" type="number" min="15" max="240" required value="60"></label><label>Location<select id="offer-location"><option>Office</option><option>Virtual</option><option>In home</option><option>In community</option></select></label></div><p class="muted">No message is sent. Offers expire after 48 hours or at session start, whichever comes first.</p><p id="offer-error" class="error" role="alert" hidden></p><div class="dialog-actions"><button type="button" data-ops-close>Cancel</button><button class="primary">Record offer</button></div></form>`);
const bookDialog=opsDialog('book-offer-dialog',`<form id="book-offer-form"><div class="dialog-heading"><h2>Record acceptance &amp; book</h2><button type="button" data-ops-close aria-label="Close booking">×</button></div><p id="book-offer-summary"></p><label class="accept-check"><input id="offer-confirmation" type="checkbox" required>I confirmed this slot with the family and recorded their acceptance.</label><p class="muted">This records a scheduling decision, not a clinical consent or electronic signature.</p><p id="book-offer-error" class="error" role="alert" hidden></p><div class="dialog-actions"><button type="button" data-ops-close>Cancel</button><button class="primary">Confirm &amp; book session</button></div></form>`);
function paintTasks(){if(!workspace)return;const q=byId('task-search').value.trim().toLowerCase();const rows=workTasks.filter(t=>`${t.title} ${caseLabel(t.case_id)}`.toLowerCase().includes(q));byId('task-count').textContent=`${rows.length} matching tasks from ${workTasks.length} loaded · Due dates use ${workspace.timezone}`;byId('task-board').innerHTML=rows.map(t=>`<article class="ops-card"><div><span class="status ${t.overdue?'overdue':''}">${t.completed_at?'Completed':t.overdue?'Overdue':'Open'}</span><h3>${escapeHTML(t.title)}</h3><p>${escapeHTML(caseLabel(t.case_id))} · ${escapeHTML(taskStaffName(t.assigned_user_id))}</p><p>Due ${escapeHTML(t.due_date)} · ${escapeHTML(t.priority)} priority</p></div><div class="ops-actions"><button data-task-edit="${escapeHTML(t.id)}">${t.version?'Edit task':'Assign task'}</button>${t.version?`<button data-task-state="${escapeHTML(t.id)}">${t.completed_at?'Reopen task':'Mark done'}</button>`:''}</div></article>`).join('')||'<div class="empty"><h3>No matching tasks.</h3><p>Change filters or create a follow-up task.</p></div>'}
async function loadTasks(append=false){if(!workspace)return;const generation=++taskGeneration;const next=append?taskOffset:0;const query=new URLSearchParams({status:byId('task-state-filter').value,assignee:byId('task-assignee-filter').value,priority:byId('task-priority-filter').value,offset:next,limit:100});try{const data=await api('/api/tasks?'+query);if(!workspace||generation!==taskGeneration)return;workTasks=append?[...workTasks,...data.items]:data.items;taskOffset=next+data.items.length;byId('more-tasks').hidden=data.items.length<100;paintTasks();message('')}catch(e){message(e.message)}}
function paintQueue(){if(!workspace)return;byId('waitlist-count').textContent=`${queueEntries.length} loaded entries · Priority, then oldest request first`;byId('waitlist-board').innerHTML=queueEntries.map(w=>{const s=w.starts_at?parts(w.starts_at):null;return `<article class="ops-card"><div><span class="status ${w.expired?'overdue':''}">${w.expired?'Offer expired':escapeHTML(w.status)}</span><h3>${escapeHTML(caseLabel(w.case_id))}</h3><p>${escapeHTML(w.service)} · ${escapeHTML(w.priority)} priority</p><p>Earliest ${escapeHTML(w.not_before)} · Requested ${escapeHTML(parts(w.created_at).date)}</p>${s?`<p><strong>${w.status==='Booked'?'Scheduled':'Offered'} ${escapeHTML(s.date)} at ${escapeHTML(s.time)}</strong> · ${escapeHTML(staffLabel(w.clinician_id))}</p>${w.status==='Offered'?`<p>Expires ${escapeHTML(parts(w.expires_at).date)} ${escapeHTML(parts(w.expires_at).time)}</p>`:''}`:''}${w.status==='Booked'?'<p>Session saved to the shared schedule.</p>':''}</div><div class="ops-actions">${manageQueue()&&w.status==='Waiting'?`<button data-offer="${escapeHTML(w.id)}">Record slot offer</button>`:''}${manageQueue()&&w.status==='Offered'?`${w.expired?'':`<button class="primary" data-book="${escapeHTML(w.id)}">Record acceptance &amp; book</button>`}<button data-resolve="${escapeHTML(w.id)}" data-action="Declined">Return to Waiting</button>`:''}${manageQueue()&&['Waiting','Offered'].includes(w.status)?`<button data-resolve="${escapeHTML(w.id)}" data-action="Withdrawn">Withdraw request</button>`:''}</div></article>`}).join('')||'<div class="empty"><h3>No entries in this stage.</h3><p>Choose another stage or add a request.</p></div>'}
async function loadQueue(append=false){if(!workspace)return;const generation=++queueGeneration;const next=append?queueOffset:0;try{const data=await api('/api/waitlist?'+new URLSearchParams({status:byId('waitlist-state-filter').value,offset:next,limit:100}));if(!workspace||generation!==queueGeneration)return;queueEntries=append?[...queueEntries,...data.items]:data.items;queueOffset=next+data.items.length;byId('more-waitlist').hidden=data.items.length<100;paintQueue();message('')}catch(e){message(e.message)}}
function taskAssigneeOptions(){const old=byId('work-task-assignee').value;const cid=byId('work-task-case').value;const staff=workspace.task_staff.filter(s=>workspace.task_assignments.some(a=>a.case_id===cid&&a.user_id===s.id));byId('work-task-assignee').innerHTML=staff.map(s=>`<option value="${escapeHTML(s.id)}">${escapeHTML(s.name)}</option>`).join('');byId('work-task-assignee').value=staff.some(s=>s.id===old)?old:staff.some(s=>s.id===workspace.user_id)?workspace.user_id:staff[0]?.id||''}
function openTask(id){taskEditing=workTasks.find(t=>t.id===id)||null;byId('work-task-form').reset();byId('work-task-case').innerHTML=caseSelectHTML();byId('work-task-case').value=taskEditing?.case_id||workspace.cases[0]?.id||'';taskAssigneeOptions();if(taskEditing?.assigned_user_id)byId('work-task-assignee').value=taskEditing.assigned_user_id;byId('work-task-title').value=taskEditing?.title||'';byId('work-task-due').value=taskEditing?.due_date||parts(new Date().toISOString()).date;byId('work-task-priority').value=taskEditing?.priority||'Normal';byId('work-task-heading').textContent=taskEditing?'Edit follow-up task':'Create follow-up task';byId('work-task-error').hidden=true;taskDialog.showModal()}
async function saveOpsForm(form,errorId,action,dialog,refresh){const button=form.querySelector('button.primary');if(button.disabled)return;button.disabled=true;byId(errorId).hidden=true;try{await action();dialog.close();await refresh()}catch(e){byId(errorId).textContent=e.message;byId(errorId).hidden=false}finally{button.disabled=false}}
byId('work-task-form').onsubmit=e=>{e.preventDefault();saveOpsForm(e.target,'work-task-error',()=>post('/api/tasks',{case_id:byId('work-task-case').value,title:byId('work-task-title').value.trim(),due_date:byId('work-task-due').value,assigned_user_id:byId('work-task-assignee').value,priority:byId('work-task-priority').value,...(taskEditing?{id:taskEditing.id,version:taskEditing.version}:{})}),taskDialog,loadTasks)};
byId('work-task-case').onchange=taskAssigneeOptions;byId('new-work-task').onclick=()=>openTask();byId('task-board').onclick=async e=>{const edit=e.target.closest('[data-task-edit]'),toggle=e.target.closest('[data-task-state]');if(edit)openTask(edit.dataset.taskEdit);if(toggle){const t=workTasks.find(t=>t.id===toggle.dataset.taskState);toggle.disabled=true;try{await post('/api/tasks/state',{id:t.id,version:t.version,status:t.completed_at?'Open':'Done'});await loadTasks()}catch(error){message(error.message);toggle.disabled=false}}};
for(const id of ['task-state-filter','task-assignee-filter','task-priority-filter'])byId(id).onchange=()=>loadTasks();byId('task-search').oninput=paintTasks;byId('refresh-tasks').onclick=()=>loadTasks();byId('more-tasks').onclick=()=>loadTasks(true);
byId('new-waitlist').onclick=()=>{byId('waitlist-form').reset();byId('waitlist-case').innerHTML=caseSelectHTML();byId('waitlist-earliest').value=parts(new Date().toISOString()).date;byId('waitlist-error').hidden=true;queueDialog.showModal()};
byId('waitlist-form').onsubmit=e=>{e.preventDefault();saveOpsForm(e.target,'waitlist-error',()=>post('/api/waitlist',{case_id:byId('waitlist-case').value,service:byId('waitlist-service').value.trim(),not_before:byId('waitlist-earliest').value,priority:byId('waitlist-priority').value}),queueDialog,loadQueue)};
byId('waitlist-board').onclick=async e=>{const offer=e.target.closest('[data-offer]'),book=e.target.closest('[data-book]'),resolve=e.target.closest('[data-resolve]');if(offer){offerEditing=queueEntries.find(w=>w.id===offer.dataset.offer);byId('offer-form').reset();byId('offer-case').textContent=caseLabel(offerEditing.case_id)+' · '+offerEditing.service;byId('offer-clinician').innerHTML=clinicianOptions(offerEditing.case_id);byId('offer-title').value=offerEditing.service+' session';const tomorrow=new Date(parts(new Date().toISOString()).date+'T12:00:00Z');tomorrow.setUTCDate(tomorrow.getUTCDate()+1);byId('offer-date').value=[tomorrow.toISOString().slice(0,10),offerEditing.not_before].sort().at(-1);byId('offer-error').hidden=true;offerDialog.showModal()}if(book){bookingEntry=queueEntries.find(w=>w.id===book.dataset.book);byId('book-offer-form').reset();const s=parts(bookingEntry.starts_at);byId('book-offer-summary').textContent=`${caseLabel(bookingEntry.case_id)} · ${s.date} at ${s.time} · ${staffLabel(bookingEntry.clinician_id)}`;byId('book-offer-error').hidden=true;bookDialog.showModal()}if(resolve){if(resolve.dataset.action==='Withdrawn'&&!confirm('Withdraw this waitlist request?'))return;const w=queueEntries.find(w=>w.id===resolve.dataset.resolve);resolve.disabled=true;try{await post('/api/waitlist/resolve',{id:w.id,version:w.version,action:resolve.dataset.action});await loadQueue()}catch(error){message(error.message);resolve.disabled=false}}};
byId('offer-form').onsubmit=e=>{e.preventDefault();saveOpsForm(e.target,'offer-error',()=>post('/api/waitlist/offer',{id:offerEditing.id,version:offerEditing.version,clinician_id:byId('offer-clinician').value,title:byId('offer-title').value.trim(),date:byId('offer-date').value,time:byId('offer-time').value,duration:Number(byId('offer-duration').value),location:byId('offer-location').value}),offerDialog,loadQueue)};
byId('book-offer-form').onsubmit=e=>{e.preventDefault();if(!byId('offer-confirmation').checked)return;saveOpsForm(e.target,'book-offer-error',()=>post('/api/waitlist/book',{id:bookingEntry.id,version:bookingEntry.version,confirmation:'confirmed'}),bookDialog,async()=>{await loadQueue();await loadAgenda()})};
byId('waitlist-state-filter').onchange=()=>loadQueue();byId('refresh-waitlist').onclick=()=>loadQueue();byId('more-waitlist').onclick=()=>loadQueue(true);
document.querySelectorAll('[data-tab]').forEach(b=>b.addEventListener('click',()=>{byId('tasks-panel').hidden=b.dataset.tab!=='tasks';byId('waitlist-panel').hidden=b.dataset.tab!=='waitlist';if(b.dataset.tab==='tasks')loadTasks();if(b.dataset.tab==='waitlist')loadQueue()}));
window.addEventListener('eero:workspace-ready',()=>{const chosenAssignee=byId('task-assignee-filter').value;byId('new-waitlist').hidden=!manageQueue();byId('new-work-task').disabled=!workspace.cases.length;byId('new-waitlist').disabled=!workspace.cases.length;byId('task-assignee-filter').innerHTML='<option value="">All assigned staff</option>'+workspace.task_staff.map(s=>`<option value="${escapeHTML(s.id)}">${escapeHTML(s.name)}${s.id===workspace.user_id?' (me)':''}</option>`).join('');if(Array.from(byId('task-assignee-filter').options).some(o=>o.value===chosenAssignee))byId('task-assignee-filter').value=chosenAssignee;});
window.addEventListener('eero:session-ended',()=>{workTasks=[];queueEntries=[];taskGeneration++;queueGeneration++;byId('task-board').replaceChildren();byId('waitlist-board').replaceChildren();for(const d of [taskDialog,queueDialog,offerDialog,bookDialog]){d.querySelector('form').reset();if(d.open)d.close()}});
